func TestEnumGatewayJsonrpcMessageJsonrpc(t *testing.T) {
	t.Run("NewFromString_2_0", func(t *testing.T) {
		t.Parallel()
		val, err := NewGatewayJsonrpcMessageJsonrpcFromString("2.0")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, GatewayJsonrpcMessageJsonrpc("2.0"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewGatewayJsonrpcMessageJsonrpcFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewGatewayJsonrpcMessageJsonrpcFromString("2.0")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

